import"./supabase-CGTu0p87.js";/* empty css              */import{i as c}from"./auth-Dtda0RQ8.js";import"https://esm.sh/@supabase/supabase-js@2";const n=document.body.dataset.current;document.querySelectorAll("[data-nav]").forEach(t=>{t.dataset.nav===n&&t.classList.add("active")});document.querySelectorAll(".mv-accordion-btn").forEach(t=>{t.addEventListener("click",()=>{t.closest(".mv-accordion").classList.toggle("open")})});const i={permanent:"本帰国の場合：転入届 → 国民健康保険 → 米国保険の解約 の順で進めます。住み始めた日から14日以内に転入届を提出し、あわせて国保の手続きを行いましょう。米国側の保険（医療・自動車・レンター等）も計画的に解約します。",temporary:"一時帰国の場合：住民登録ができないため国民健康保険には加入できない場合が多いです。海外旅行保険や一時帰国保険でカバーしましょう。医療費は全額自費になる可能性があります。",employed:"帰国後すぐ就職する場合：勤務先の健康保険（社保）に加入するため、国保は不要となる場合があります。ただし入社日まで空白がある場合は国保で繋ぐことを検討しましょう。自治体窓口で確認を。",freelance:"しばらく無職・フリーランスの場合：国民健康保険＋国民年金に加入します。保険料は前年所得に基づきます。経済的に厳しい場合は免除・猶予制度があるため市区町村窓口で相談しましょう。",family:"家族・子どもありの場合：国保には扶養制度がないため、家族それぞれの加入が必要です。社保に加入する場合は配偶者・子供を扶養に入れられます。子供の医療費助成制度（自治体で異なる）も確認しましょう。","us-active":"米国の保険がまだ残っている場合：帰国日に合わせて解約スケジュールを組みましょう。雇用主提供なら退職日で自動終了が多いです。個人加入なら月末締めが一般的。空白期間ができる場合はCOBRAや海外旅行保険を検討。"};document.querySelectorAll(".diagnosis-btn").forEach(t=>{t.addEventListener("click",()=>{document.querySelectorAll(".diagnosis-btn").forEach(a=>a.classList.remove("active")),t.classList.add("active");const e=t.dataset.diagnosis,o=document.getElementById("diagnosis-result"),s=document.getElementById("diagnosis-text");s.textContent=i[e],o.style.display="block"})});c();
